publicAPLRes:AskPluginLoad2(Handle:myself, bool:late, String:error\[\], err\_max)

{

CreateNative("IsInPause", Native\_IsInPause);

pauseForward=CreateGlobalForward("OnPause", ET\_Event);

unpauseForward=CreateGlobalForward("OnUnpause", ET\_Event);

RegPluginLibrary("pause");

MarkNativeAsOptional("IsInReady");

returnAPLRes\_Success;

}

publicOnPluginStart()

{

RegConsoleCmd("sm\_pause", Pause\_Cmd, "Pauses the game");

RegConsoleCmd("sm\_unpause", Unpause\_Cmd, "Marks your team as ready for an unpause");

RegConsoleCmd("sm\_ready", Unpause\_Cmd, "Marks your team as ready for an unpause");

RegConsoleCmd("sm\_unready", Unready\_Cmd, "Marks your team as ready for an unpause");

RegConsoleCmd("sm\_toggleready", ToggleReady\_Cmd, "Toggles your team's ready status");

RegAdminCmd("sm\_forcepause", ForcePause\_Cmd, ADMFLAG\_BAN, "Pauses the game and only allows admins to unpause");

RegAdminCmd("sm\_forceunpause", ForceUnpause\_Cmd, ADMFLAG\_BAN, "Unpauses the game regardless of team ready status. Must be used to unpause admin pauses");

AddCommandListener(Say\_Callback, "say");

AddCommandListener(TeamSay\_Callback, "say\_team");

AddCommandListener(Unpause\_Callback, "unpause");

sv\_pausable=FindConVar("sv\_pausable");

sv\_noclipduringpause=FindConVar("sv\_noclipduringpause");

pauseDelayCvar=CreateConVar("sm\_pausedelay", "0", "Delay to apply before a pause happens. Could be used to prevent Tactical Pauses", FCVAR\_PLUGIN, true, 0.0);

l4d\_ready\_delay=CreateConVar("l4d\_ready\_delay", "5", "Number of seconds to count down before the round goes live.", FCVAR\_PLUGIN, true, 0.0);

l4d\_ready\_blips=CreateConVar("l4d\_ready\_blips", "1", "Enable beep on unpause");

HookEvent("round\_end", RoundEnd\_Event, EventHookMode\_PostNoCopy);

HookEvent("player\_team", PlayerTeam\_Event);

}

publicOnAllPluginsLoaded()

{

readyUpIsAvailable=LibraryExists("readyup");

}

publicOnLibraryRemoved(constString:name\[\])

{

if (StrEqual(name, "readyup")) readyUpIsAvailable=false;

}

publicOnLibraryAdded(constString:name\[\])

{

if (StrEqual(name, "readyup")) readyUpIsAvailable=true;

}

publicNative\_IsInPause(Handle:plugin, numParams)

{

return\_:isPaused;

}

publicOnClientPutInServer(client)

{

if (isPaused)

{

if (!IsFakeClient(client))

{

PrintToChatAll("\\x01\[SM\] \\x03%N\\x01is now fully loaded in game", client);

ChangeClientTeam(client, \_:L4D2Team\_Spectator);

}

}

}

publicOnMapStart()

{

PrecacheSound("buttons/blip2.wav");

}

publicRoundEnd\_Event(Handle:event, constString:name\[\], bool:dontBroadcast)

{

if (deferredPauseTimer!=INVALID\_HANDLE)

{

{

if (isPaused)

{

returnPlugin\_Handled;

}

returnPlugin\_Continue;

}

bool:CheckFullReady()

{

return (teamReady\[L4D2Team\_Survivor\] \|\|GetTeamHumanCount(L4D2Team\_Survivor) ==0)

&& (teamReady\[L4D2Team\_Infected\] \|\|GetTeamHumanCount(L4D2Team\_Infected) ==0);

}

stockIsPlayer(client)

{

newL4D2Team:team=L4D2Team:GetClientTeam(client);

return (client&& (team==L4D2Team\_Survivor\|\|team==L4D2Team\_Infected));

}

