{

if(IsClientInGame(client) &&L4D2Team:GetClientTeam(client) ==team)

{

CPrintToChatEx(client, author, "(%s) {teamcolor}%N{default} : %s", teamString\[L4D2Team:GetClientTeam(author)\], author, buffer);

}

}

}

