stockGetTeamHumanCount(L4D2Team:team)

{

newhumans=0;

for (newclient=1; client<=MaxClients; client++)

{

if (IsClientInGame(client) &&!IsFakeClient(client) &&L4D2Team:GetClientTeam(client) ==team)

{

humans++;

}

}

returnhumans;

}

