bool:CanPause()

{

for (newclient=1; client<=MaxClients; client++)

{

if(IsClientInGame(client) &&IsPlayerAlive(client) &&L4D2Team:GetClientTeam(client) ==L4D2Team\_Survivor)

{

if (IsPlayerIncap(client))

{

if (GetEntProp(client, Prop\_Send, "m\_reviveOwner") >0)

{

returnfalse;

}

}

else

{

if (GetEntProp(client, Prop\_Send, "m\_reviveTarget") >0)

{

returnfalse;

}

}

}

}

returntrue;

